/// The all-clear (AC) key's own colours: a warm, alert key that stands
/// apart from the digit, function, operator and `=` keys of every theme.
///
/// Users could not find AC when it wore the function keys' colours, so
/// `KeyRole.clear` gets a colour group of its own. It is *derived* from a
/// finished [ThemeSpec] (its palette, family, Accessible lock, steering
/// chroma and seed) rather than drawn by the generator, so:
///
/// - every theme has one, including themes generated by older engine
///   versions, heroes, saved favourites and share codes;
/// - no [ThemeSpec] changes: `toJson`, `stableHash` and every golden
///   fixture are exactly as before, and no engine version bump is needed.
///
/// The derivation is part of the bit-exact engine: pure Dart, seeded only
/// through [Rng.stream] (`palette/clear`), identical on every platform.
/// It is frozen for engine versions 1–5 (pinned by
/// `test/engine/fixtures/clear_keys.json`). Any change to it must be gated
/// on a new engine version, like generator changes.
///
/// How the colour is chosen:
///
/// 1. The key takes the structure of the family's accent key (its
///    "template"): the operator, or `=` in Neumorphism and Paper & ink,
///    where `=` is the one filled key. Alpha (Liquid Glass tints), the
///    label's tint and an edge that follows the face (NeoPOP sides, Retro
///    skirts, clay shadows, Bauhaus blocks) carry over; an edge that is
///    the family's ink or rim (Neo-brutalism, Paper & ink, Y2K, glass,
///    Vaporwave, Neumorphism) stays as it is.
/// 2. Its hue turns to an alert colour: red first, then vermilion,
///    crimson, amber and rose, each jittered by up to ±6° from the
///    theme's seed. Bauhaus picks among its three primaries instead (red,
///    yellow, blue). Chroma is at least the family's floor (muted
///    intents keep a softer floor, Cyberpunk stays neon).
/// 3. The first candidate (keeping the template's lightness, then moving
///    it by up to 0.42) whose label passes the theme's label policy (4.5:1,
///    7:1 under the Accessible lock), that passes the family's own
///    guardrails in the template's place, and that differs from the
///    digit, function, operator and `=` faces by [clearMinCvdDeltaE] under
///    normal, protan, deutan and tritan vision (and from the digit and
///    function faces by [clearMinDeltaE] in normal vision) wins. Labels
///    keep the family's polarity where the family requires it (Y2K gels
///    carry dark labels). A translucent glass tint goes solid only when no
///    tint passes.
/// 4. If no candidate passes everything, the most distinct one that keeps
///    the family's rules wins when it reaches [clearFallbackScore] of the
///    floors, else the most distinct one with a passing label. In practice
///    this only happens in Y2K (its gels must stay in a light lightness
///    band, where some themes leave room for about 0.75 of the floors; the
///    AC gel still differs from the metal digit and function keys by
///    material) and in a few steered themes.
library;

import 'package:calsee_themes/engine/bitexact_math.dart';
import 'package:calsee_themes/engine/claymorphism.dart' show clayDropShadow;
import 'package:calsee_themes/engine/contrast.dart';
import 'package:calsee_themes/engine/cvd.dart';
import 'package:calsee_themes/engine/guardrails.dart';
import 'package:calsee_themes/engine/oklab.dart';
import 'package:calsee_themes/engine/rng.dart';
import 'package:calsee_themes/engine/theme_intent.dart';
import 'package:calsee_themes/engine/theme_spec.dart';

/// The AC face's least ΔEOK from the digit, function, operator and `=`
/// faces, under normal vision and each simulated colour-vision deficiency.
const double clearMinCvdDeltaE = 0.08;

/// The AC face's least ΔEOK from the digit and function faces under
/// normal vision (the keys users mistook it for).
const double clearMinDeltaE = 0.12;

/// When no candidate passes everything, the most distinct candidate that
/// keeps the family's rules wins if it reaches this fraction of the
/// distinctness floors; otherwise the most distinct candidate does.
const double clearFallbackScore = 0.75;

/// The RNG stream of the AC hue jitter.
final String clearKeyTag = RngTag.sub(RngTag.palette, 'clear');

/// Alert hues (OKLCH degrees) in order of preference: red, vermilion,
/// crimson, amber, rose.
const List<double> clearAlertHues = [29, 45, 12, 66, 352];

/// Bauhaus's primaries (OKLCH lightness, chroma, hue: red, yellow, blue)
/// for its AC block.
const List<(double, double, double)> clearBauhausPrimaries = [
  (0.55, 0.2, 31),
  (0.86, 0.17, 90),
  (0.45, 0.16, 266),
];

/// Lightness offsets tried from the template's lightness, in order.
const List<double> clearLightnessSteps = [
  0,
  -0.035,
  0.035,
  -0.07,
  0.07,
  -0.105,
  0.105,
  -0.14,
  0.14,
  -0.21,
  0.21,
  -0.28,
  0.28,
  -0.35,
  0.35,
  -0.42,
  0.42,
];

/// The palette slot whose look the AC key takes.
enum ClearTemplate { operator, equals }

/// The template slot of [family].
ClearTemplate clearTemplateOf(ThemeFamily family) => switch (family) {
  ThemeFamily.neumorphism || ThemeFamily.paperInk => ClearTemplate.equals,
  _ => ClearTemplate.operator,
};

/// Whether [family]'s key edge follows the face (NeoPOP sides, Retro
/// skirts, clay shadows, M3 Expressive outlines, Cyberpunk glows, Bauhaus
/// blocks) and so turns with it; the other families' edge is their ink or
/// rim and stays.
bool clearEdgeTracksFace(ThemeFamily family) => switch (family) {
  ThemeFamily.neoBrutalism ||
  ThemeFamily.paperInk ||
  ThemeFamily.y2kChrome ||
  ThemeFamily.neumorphism ||
  ThemeFamily.liquidGlass ||
  ThemeFamily.vaporwave => false,
  _ => true,
};

final Expando<KeyColors> _cache = Expando('clearKeyColors');

/// The AC key's colours for [spec] (memoised per spec instance).
KeyColors clearKeyColors(ThemeSpec spec) => _cache[spec] ??= _derive(spec);

/// How far [clear] stands apart from [spec]'s other key faces, as a
/// fraction of the AC floors ([clearMinCvdDeltaE], [clearMinDeltaE]): ≥ 1
/// meets them all (tests and diagnostics).
double clearKeyDistinctness(ThemeSpec spec, KeyColors clear) =>
    _distinctness(spec, clear, backgroundSamples(spec.background));

/// The AC rules [clear] breaks for [spec] (empty: it passes): `label`
/// (below the theme's label floor on its face), `distinct` (too close to
/// another key face), or `family:<rule>` (a family guardrail it breaks in
/// its template's place). Tests and diagnostics.
List<String> clearKeyViolations(ThemeSpec spec, KeyColors clear) {
  final lim = GuardrailLimits.forSpec(spec);
  final bgs = backgroundSamples(spec.background);
  final out = <String>[];
  for (final f in faceSamples(clear.face, bgs)) {
    if (contrastOver(clear.label, f) < lim.labelRatio) {
      out.add('label');
      break;
    }
  }
  if (_distinctness(spec, clear, bgs) < 1) out.add('distinct');
  final original = {for (final v in validateTheme(spec)) v.rule};
  for (final rule in _familyViolations(spec, clear, original)) {
    out.add('family:${rule.name}');
  }
  return out;
}

KeyColors _derive(ThemeSpec spec) {
  final p = spec.palette;
  final template = clearTemplateOf(spec.family);
  final base = switch (template) {
    ClearTemplate.operator => p.operator,
    ClearTemplate.equals => p.equals,
  };
  final lim = GuardrailLimits.forSpec(spec);
  final bgs = backgroundSamples(spec.background);
  final baseLch = argbToOklch(base.face);
  final edgeLch = argbToOklch(base.edge);
  final edgeTracks = clearEdgeTracksFace(spec.family);
  final bauhaus = spec.family == ThemeFamily.bauhaus;
  final jitter = bauhaus
      ? 0.0
      : Rng.stream(spec.seed, clearKeyTag).nextJitterTenths(60) / 10;
  final muted = spec.intent?.effectiveChroma == IntentChroma.muted;
  final floor = switch (spec.family) {
    ThemeFamily.cyberpunk => 0.2,
    // Y2K gels keep a light, narrow lightness band: colour carries them.
    ThemeFamily.y2kChrome => muted ? 0.12 : 0.17,
    _ => muted ? 0.09 : 0.13,
  };
  final chroma = baseLch.c > floor ? baseLch.c : floor;
  // Anchors (lightness, chroma, hue): the alert hues at the template's
  // lightness (Bauhaus: its primaries as they are), then, when none of
  // those can stand apart, the rest of the wheel.
  final tiers = [
    if (bauhaus)
      [for (final (l, c, h) in clearBauhausPrimaries) (l, c, h)]
    else
      [for (final h in clearAlertHues) (baseLch.l, chroma, _wrap(h + jitter))],
    [
      for (var h = 0; h < 360; h += 30)
        (baseLch.l, chroma, _wrap(h + 15 + jitter)),
    ],
  ];
  final original = validateTheme(spec, limits: lim).map((v) => v.rule).toSet();
  // A translucent template (Liquid Glass) keeps its alpha; only when no
  // tint can carry a passing label and stand apart (the Accessible lock's
  // 7:1 over a busy mesh) does the AC key go solid.
  final alphas = [
    base.face & 0xFF000000,
    if ((base.face >>> 24) != 0xFF) 0xFF000000,
  ];

  KeyColors? best;
  var bestScore = -1.0;
  KeyColors? bestAny;
  var bestAnyScore = -1.0;
  for (final (alpha, anchors) in [
    for (final a in alphas)
      for (final t in tiers) (a, t),
  ]) {
    for (final step in clearLightnessSteps) {
      for (final (l0, c, h) in anchors) {
        final l = l0 + step;
        if (l < 0.12 || l > 0.95) continue;
        final face = alpha | (oklchToArgb(l, c, h) & 0x00FFFFFF);
        final label = _label(
          face,
          base.label,
          lim,
          bgs,
          darkOnly: spec.family == ThemeFamily.y2kChrome,
        );
        if (label == null) continue;
        final int edge;
        if (spec.family == ThemeFamily.claymorphism) {
          // Clay's own drop shadow for the new face (tinted, darker than
          // the body; claymorphism.dart).
          final body = argbToOklch(spec.background.colors.first | 0xFF000000);
          edge = clayDropShadow(
            face,
            bodyHueTenths: (body.h * 10).round() % 3600,
            dark: spec.isDark,
            group: KeyGroup.operator,
            baseL: body.l,
            baseC: body.c,
          );
        } else if (base.edge == base.face) {
          edge = face;
        } else if (edgeTracks) {
          final ratio = baseLch.c > 0.001 ? c / baseLch.c : 1.0;
          edge =
              (base.edge & 0xFF000000) |
              (oklchToArgb(
                    clamp01(edgeLch.l + (l - baseLch.l)),
                    edgeLch.c * ratio,
                    h,
                  ) &
                  0x00FFFFFF);
        } else {
          edge = base.edge;
        }
        final candidate = KeyColors(face: face, label: label, edge: edge);
        final score = _distinctness(spec, candidate, bgs);
        // Out-of-gamut anchors lose chroma: a washed-out AC is no alert.
        final got = argbToOklch(face).c;
        final vivid = got >= c * 0.6 || got >= 0.12;
        if (score < 1 && score <= bestScore && score <= bestAnyScore) continue;
        final family = _familyPasses(spec, candidate, original);
        if (score >= 1 && vivid && family) return candidate;
        if (family && score > bestScore) {
          bestScore = score;
          best = candidate;
        }
        if (score > bestAnyScore) {
          bestAnyScore = score;
          bestAny = candidate;
        }
      }
    }
  }
  // No candidate passed everything: the most distinct one that keeps the
  // family's rules, else the most distinct one with a passing label. A
  // label always passes somewhere (black or white at some lightness).
  if (best != null && (bestScore >= clearFallbackScore || bestAny == null)) {
    return best;
  }
  return bestAny ?? base;
}

/// A label for [face] from [start] meeting [lim]'s label policy. With
/// [darkOnly] (Y2K gels, whose labels are always dark) only a label darker
/// than the face will do.
int? _label(
  int face,
  int start,
  GuardrailLimits lim,
  List<int> bgs, {
  bool darkOnly = false,
}) {
  if (((face >>> 24) & 0xFF) == 255) {
    final from = argbToOklch(start);
    if (darkOnly) {
      final faceY = luminanceArgb(face);
      final dark = solveLightness(
        l0: from.l,
        c: from.c,
        hDeg: from.h,
        againstArgb: face,
        target: lim.labelPolicy.targetFor(faceY),
        preferLighter: false,
      );
      return dark != null && luminanceArgb(dark) < faceY ? dark : null;
    }
    return solveLabel(face, from, policy: lim.labelPolicy);
  }
  return solveOnAll(start, faceSamples(face, bgs), lim.labelRatio);
}

/// The AC face's worst distinctness as a fraction of its floors (≥ 1:
/// distinct enough).
double _distinctness(ThemeSpec spec, KeyColors clear, List<int> bgs) {
  final p = spec.palette;
  final faces = [for (final f in faceSamples(clear.face, bgs)) cvdLabs(f)];
  var worst = double.infinity;
  for (final (other, normalFloor) in [
    (p.digit, clearMinDeltaE),
    (p.function, clearMinDeltaE),
    (p.operator, 0.0),
    (p.equals, 0.0),
  ]) {
    final others = [for (final o in faceSamples(other.face, bgs)) cvdLabs(o)];
    // Two translucent faces are compared over the same background sample
    // (neighbouring keys sit on the same part of the scene).
    final paired = others.length == faces.length && faces.length > 1;
    for (var i = 0; i < faces.length; i++) {
      for (var j = 0; j < others.length; j++) {
        if (paired && i != j) continue;
        final f = faces[i];
        final labs = others[j];
        final cvd = minCvdDeltaELabs(f, labs) / clearMinCvdDeltaE;
        if (cvd < worst) worst = cvd;
        if (normalFloor > 0) {
          final normal = deltaEOK(f.first, labs.first) / normalFloor;
          if (normal < worst) worst = normal;
        }
      }
    }
  }
  return worst;
}

/// Whether [spec] with [clear] in its template slot breaks no family rule
/// it did not already break.
bool _familyPasses(
  ThemeSpec spec,
  KeyColors clear,
  Set<GuardrailRule> original,
) => _familyViolations(spec, clear, original).isEmpty;

Iterable<GuardrailRule> _familyViolations(
  ThemeSpec spec,
  KeyColors clear,
  Set<GuardrailRule> original,
) {
  final p = spec.palette;
  final swapped = spec.copyWith(
    palette: switch (clearTemplateOf(spec.family)) {
      ClearTemplate.operator => p.copyWith(operator: clear),
      ClearTemplate.equals => p.copyWith(equals: clear),
    },
  );
  return {
    for (final v in validateTheme(swapped))
      if (!original.contains(v.rule)) v.rule,
  };
}

double _wrap(double h) => h < 0 ? h + 360 : (h >= 360 ? h - 360 : h);
